import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        // Fund the contract so it has Ether to send
        vm.deal(address(c), amount + 1);
        // Set up the owner
        address owner = address(uint160(uint256(keccak256(abi.encode("owner")))));
        vm.deal(owner, amount);
        vm.startPrank(owner);
        // Give the contract a deterministic owner by calling through the original constructor's logic simulation
        // We need to set owner; since constructor sets it to deployer, we can't change it. We'll deploy as owner.
        vm.stopPrank();
        // Re-deploy with the fuzzed owner to satisfy require(msg.sender == owner)
        vm.prank(owner);
        c = new C();
        vm.deal(address(c), amount + 1);
        vm.prank(owner);
        bool ok = true;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        // Rule: if the call reverted, the contract balance must be less than amount.
        // The reference only reverts on send failure which happens when contract balance < amount (transfer fails if balance insufficient).
        // The buggy version additionally reverts if the 4th require fails even when balance is sufficient, making ok false while balance >= amount.
        // Since we funded contract with amount+1, balance >= amount. Reference succeeds (ok true), bug reverts (ok false).
        // So assert that !ok implies address(c).balance < amount.
        assertTrue(!ok ? address(c).balance < amount : true);
    }
}

