pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(amount > 0);
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        uint256 balBefore = receiver.balance;
        vm.prank(address(c).balance == 0 ? address(1) : address(0));
        // We need to call sendTo as the owner. Since constructor sets owner as deployer (this contract),
        // we can prank ourselves if we are the owner. But setUp deploys, so address(this) is owner.
        // However, sendTo sends ether, so we need to have ether. But we don't need to send ether from the caller,
        // sendTo uses transfer which sends from the contract. So the contract needs ether.
